var t=`0889-hoppers-appam`;var n=`world-0889`;var a=`LK`;var r=`south-asia`;var s=8;var o=573;var c={en:`Hoppers (Appam)`,ua:`Хоперс (аппам)`};var d={en:`Hoppers (Appam) is a Sri Lanka dish made with white rice, coconut milk, instant yeast, chicken egg. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Хоперс (аппам), страва кухні країни Шрі-Ланка. Основні складники: білий рис, кокосове молоко, інстантні дріжджі, куряче яйце. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Soak the listed rice, grains or noodles in clean water for about 240 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 240 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`rice-soaking`],m:240,i:[[`white-rice`,350,`g`],[`water`,950,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`coconut-milk`,250,`ml`],[`instant-yeast`,4,`g`],[`white-granulated-sugar`,20,`g`]]},{en:`Leave the mixed rice-and-legume batter loosely covered in a clean warm place for about 300 minutes until aerated and tangy. Fermentation times vary; avoid overheating.`,ua:`Залиште суміш рисового тіста з бобовими нещільно накритою в чистому теплому місці на приблизно 300 хвилин до бульбашок та легкої кислинки. Час змінюється; не перегрівайте.`,t:[`mixed-grain-fermentation`],m:300,i:[]},{en:`Swirl coconut-rice batter up the sides of a small hopper pan; for egg hoppers, crack an egg into the center and cover until fully set.`,ua:`Розлийте кокосово-рисове тісто по стінках маленької сковороди для хоперс; для яєчного варіанта вбийте яйце в середину й готуйте під кришкою до готовності.`,t:[`griddle-cooking`],m:18,i:[[`coconut-oil`,30,`ml`],[`chicken-egg`,3,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,10,`g`]]}];var l={slug:t,id:n,country:`LK`,region:r,servings:8,minutes:573,title:c,text:d,steps:g};export{a as country,l as default,n as id,o as minutes,r as region,s as servings,t as slug,g as steps,d as text,c as title};